using System;
using System.Collections.Generic;
using System.IO;
namespace SlopStudio {
 // Original PCM multisamples, generated once outside the real-time callback. No third-party samples.
 public sealed class SamplerSample {public int Root,Rate,LoopStart,LoopEnd;public float[] Pcm;public bool Loop;}
 public static class SamplerBank {
  private static readonly Dictionary<string,SamplerSample[]> Banks=new Dictionary<string,SamplerSample[]>();
  public static SamplerSample[] Load(string preset){lock(Banks){SamplerSample[] bank;if(Banks.TryGetValue(preset,out bank))return bank;bool drum=preset=="Drum Kit";var list=new List<SamplerSample>();for(int root=drum?35:24;root<=(drum?81:108);root+=drum?1:12){int rate=24000;int count=rate*(drum?1:3);float[] pcm=new float[count];double frequency=440*Math.Pow(2,(root-69)/12.0);uint seed=(uint)(7919+root*29);for(int i=0;i<count;i++){double t=i/(double)rate,p=2*Math.PI*frequency*t,value;if(drum){seed^=seed<<13;seed^=seed>>17;seed^=seed<<5;double noise=seed/(double)UInt32.MaxValue*2-1;value=root==35||root==36?Math.Sin(2*Math.PI*(47*t+2.6*(1-Math.Exp(-t*35))))*Math.Exp(-t*9):(root==38||root==40)?(noise*.65+Math.Sin(2*Math.PI*185*t)*.35)*Math.Exp(-t*16):noise*Math.Exp(-t*(root==46?11:42));}else if(preset=="Sub Bass")value=Math.Sin(p)*.85+Math.Sin(2*p)*.12;else if(preset=="Analog Lead")value=(Math.Sin(p)+.42*Math.Sin(2*p)+.23*Math.Sin(3*p)+.13*Math.Sin(4*p))*.64;else if(preset=="Warm Pad")value=(Math.Sin(p)+Math.Sin(p*1.002)*.23+Math.Sin(2*p)*.15)*.68;else if(preset=="Pluck")value=(Math.Sin(p)+.28*Math.Sin(3*p))*Math.Exp(-t*4.5);else if(preset=="Soft Piano")value=(Math.Sin(p)+.22*Math.Sin(2*p)+.1*Math.Sin(3*p))*Math.Exp(-t*1.35);else value=Math.Sin(p+1.4*Math.Sin(p*2)*Math.Exp(-t*3.5))*Math.Exp(-t*.52);pcm[i]=(float)(value*Math.Min(1,t/.003));}bool loop=preset=="Sub Bass"||preset=="Analog Lead"||preset=="Warm Pad";int end=count-1,start=end-(int)Math.Round(rate/frequency*32);if(loop){int cross=Math.Min(128,(end-start)/4);for(int j=0;j<cross;j++){float a=j/(float)cross;pcm[end-cross+j]=pcm[end-cross+j]*(1-a)+pcm[start-cross+j]*a;}}list.Add(new SamplerSample{Root=root,Rate=rate,Pcm=pcm,Loop=loop,LoopStart=start,LoopEnd=end});}bank=list.ToArray();Banks[preset]=bank;return bank;}}
  private static readonly Dictionary<string,SamplerSample[]> Imported=new Dictionary<string,SamplerSample[]>();
  public static SamplerSample[] LoadFile(string path,int root){var info=new FileInfo(path);if(!info.Exists)throw new FileNotFoundException("Sampler audio file is missing.",path);string key=info.FullName+"|"+info.Length+"|"+info.LastWriteTimeUtc.Ticks+"|"+root;lock(Imported){SamplerSample[] found;if(Imported.TryGetValue(key,out found))return found;var audio=CachedAudio.Load(info.FullName);if(audio.Frames<2)throw new InvalidDataException("Sampler audio must contain at least two frames.");var mono=new float[audio.Frames];for(int i=0;i<mono.Length;i++)mono[i]=audio.Channels==1?audio.Samples[i]:(audio.Samples[i*audio.Channels]+audio.Samples[i*audio.Channels+1])*.5f;found=new[]{new SamplerSample{Root=root,Rate=audio.Rate,Pcm=mono,Loop=false,LoopStart=0,LoopEnd=Math.Max(0,mono.Length-1)}};Imported[key]=found;return found;}}
 }
 public class SamplerInstrument {
  private sealed class Voice {public bool Active,Gate,Sustained,Peaked;public int Pitch,Channel;public double Position,Step,Envelope,Velocity;public SamplerSample Sample;}
  private readonly Voice[] _voices=new Voice[64];private readonly bool[] _sustain=new bool[16];private readonly double[] _bend=new double[16];private SamplerSample[] _bank;private string _preset,_source;private int _steal;private double _attack=.004,_decay=.1,_sustainLevel=1,_release=.065;
  public SamplerInstrument(){for(int i=0;i<64;i++)_voices[i]=new Voice();for(int i=0;i<16;i++)_bend[i]=1;}
  public void Prepare(string preset){Prepare(preset,null);}
  public void Prepare(string preset,SamplerSettings settings){string source;if(String.IsNullOrWhiteSpace(settings==null?null:settings.SamplePath))source="builtin:"+preset;else{var file=new FileInfo(settings.SamplePath);if(!file.Exists)throw new FileNotFoundException("Sampler audio file is missing.",settings.SamplePath);source=file.FullName+"|"+file.Length+"|"+file.LastWriteTimeUtc.Ticks+"|"+settings.RootNote;}if(_preset!=preset||_source!=source||_bank==null){_bank=settings!=null&&!String.IsNullOrWhiteSpace(settings.SamplePath)?SamplerBank.LoadFile(settings.SamplePath,settings.RootNote):SamplerBank.Load(preset);_preset=preset;_source=source;Reset();}_attack=settings==null?(preset=="Warm Pad"?.08:.004):settings.Attack;_decay=settings==null?.1:settings.Decay;_sustainLevel=settings==null?1:settings.Sustain;_release=settings==null?(preset=="Warm Pad"?.3:.065):settings.Release;}
  public void Reset(){foreach(var v in _voices)v.Active=false;Array.Clear(_sustain,0,16);}
  private void Event(MidiEventPacket e,int rate){int type=e.Status&240,ch=e.Status&15;if(type==0x90&&e.Data2>0){Voice voice=null;foreach(var v in _voices)if(!v.Active){voice=v;break;}if(voice==null)voice=_voices[_steal++%64];var sample=_bank[0];foreach(var s in _bank)if(Math.Abs(s.Root-e.Data1)<Math.Abs(sample.Root-e.Data1))sample=s;voice.Active=voice.Gate=true;voice.Sustained=false;voice.Peaked=false;voice.Pitch=e.Data1;voice.Channel=ch;voice.Sample=sample;voice.Position=voice.Envelope=0;voice.Step=sample.Rate/(double)rate*Math.Pow(2,(e.Data1-sample.Root)/12.0);voice.Velocity=Math.Pow(e.Data2/127.0,1.3);}
   else if(type==0x80||(type==0x90&&e.Data2==0)){foreach(var v in _voices)if(v.Active&&v.Pitch==e.Data1&&v.Channel==ch){v.Gate=false;v.Sustained=_sustain[ch];}}
   else if(type==0xb0&&e.Data1==64){_sustain[ch]=e.Data2>=64;if(!_sustain[ch])foreach(var v in _voices)if(v.Channel==ch)v.Sustained=false;}
   else if(type==0xb0&&(e.Data1==120||e.Data1==123)){foreach(var v in _voices)if(v.Channel==ch)v.Active=false;}
   else if(type==0xe0)_bend[ch]=Math.Pow(2,((e.Data1+(e.Data2<<7)-8192)/8192.0)*2/12);
  }
  public void Render(float[] output,int frames,int rate,string preset,MidiEventPacket[] events,int count){if(_bank==null||_preset!=preset)Prepare(preset);int next=0;double attack=1.0/(rate*Math.Max(.000001,_attack)),decay=(1-_sustainLevel)/(rate*Math.Max(.000001,_decay)),release=_release<=0?0:Math.Exp(-6.0/(rate*_release));for(int i=0;i<frames;i++){while(next<count&&events[next].Offset<=i)Event(events[next++],rate);double mixed=0;foreach(var v in _voices){if(!v.Active)continue;var s=v.Sample;int position=(int)v.Position;if(position+1>=s.Pcm.Length){v.Active=false;continue;}double frac=v.Position-position;if(v.Gate||v.Sustained){if(!v.Peaked){v.Envelope=Math.Min(1,v.Envelope+attack);if(v.Envelope>=1)v.Peaked=true;}else v.Envelope=Math.Max(_sustainLevel,v.Envelope-decay);}else v.Envelope*=release;if(v.Envelope<.00005&&!v.Gate&&!v.Sustained){v.Active=false;continue;}mixed+=(s.Pcm[position]*(1-frac)+s.Pcm[position+1]*frac)*v.Envelope*v.Velocity*.12;v.Position+=v.Step*_bend[v.Channel];if(s.Loop&&v.Position>=s.LoopEnd)v.Position=s.LoopStart+(v.Position-s.LoopStart)%(s.LoopEnd-s.LoopStart);}output[i*2]+=(float)mixed;output[i*2+1]+=(float)mixed;}}
 }
 internal sealed class BuiltinInstrument:SamplerInstrument{}
}
